-- 0080_price_basis_halt_step21_review.sql
-- Шаг 22.
-- 1. Р-116: сверка базы цены при обратном чтении. Если канал применил нашу цену, но покупатель видит сумму, отличающуюся от
--    отправленной ровно на ставку НДС товара, — это неверная база цены (канал считает брутто нетто или наоборот). Диспетчер ставит
--    системную остановку витрины с причиной CHANNEL_PRICE_BASIS_MISMATCH (packages/write-dispatcher, checkPriceBasis хранилища).
--    В отличие от остановки по массовому сдвигу [Р-51], она блокирует ЛЮБУЮ цену: канал применяет каждую нашу сумму с той же
--    ошибкой, фиксированную и маржинальную тоже. Выборкой не снимается (review_halt_by_sample проверяет только CHANNEL_MASS_SHIFT,
--    0063, 0065) — только человеком со вторым фактором (0058). Две остановки одной витрины с разными причинами сосуществуют.
-- 2. Реестры параметров слепка (0066, 0070) — новые коды Р-115 (CHANNEL_REPRICER_ACTIVE, CHANNEL_BOUNDS_PRESENT, действия продавца)
--    и Р-116; совпадение с кодом проверяет undercut-eternal.pg.test.ts.
-- 3. Находка 7 ревью шага 21: tenant_data.row_in_current_transaction(xid) была объявлена STABLE PARALLEL SAFE, но читает состояние
--    текущей транзакции (pg_current_xact_id, pg_xact_status) — VOLATILE PARALLEL RESTRICTED.
-- 4. Р-114 исправила причину Р-111: комментарии ограничений 0077.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Р-116
-- ---------------------------------------------------------------------------
ALTER TABLE channel_data.pricing_halt DROP CONSTRAINT pricing_halt_system_only;
ALTER TABLE channel_data.pricing_halt
  ADD CONSTRAINT pricing_halt_system_only CHECK (reason_code IN ('CHANNEL_MASS_SHIFT', 'CHANNEL_PRICE_BASIS_MISMATCH'));
COMMENT ON CONSTRAINT pricing_halt_system_only ON channel_data.pricing_halt IS
  'Р-69, Р-116: системная остановка — только по испорченным данным канала на входе (массовый сдвиг) или на выходе (неверная база цены)';

DROP INDEX channel_data.pricing_halt_active_uq;
-- Одна действующая остановка на аккаунт, витрину и причину: повтор вставки той же причины — ON CONFLICT DO NOTHING в хранилище
-- (insertHalt, checkPriceBasis); остановки по массовому сдвигу и по базе цены одной витрины сосуществуют [Р-116]
CREATE UNIQUE INDEX pricing_halt_active_uq ON channel_data.pricing_halt (tenant_id, channel_account_id, (COALESCE(marketplace, '*')), reason_code)
  WHERE released_at IS NULL;

/** Действующая остановка витрины по неверной базе цены для единицы записи [Р-116] */
CREATE FUNCTION channel_data.price_basis_halt_for(p_tenant_id uuid, p_write_scope_id uuid) RETURNS uuid
  LANGUAGE sql STABLE AS $$
  SELECT h.pricing_halt_id
    FROM tenant_data.write_scope s
    JOIN channel_data.pricing_halt h
      ON h.tenant_id = s.tenant_id AND h.channel_account_id = s.channel_account_id AND h.released_at IS NULL
     AND h.reason_code = 'CHANNEL_PRICE_BASIS_MISMATCH'
   WHERE s.tenant_id = p_tenant_id AND s.write_scope_id = p_write_scope_id
     AND (h.marketplace IS NULL OR EXISTS (
           SELECT 1 FROM tenant_data.offer_mapping m
            WHERE m.tenant_id = s.tenant_id AND m.price_write_scope_id = s.write_scope_id AND m.marketplace = h.marketplace))
   LIMIT 1
$$;

-- Одобрение любой цены при остановке по базе цены — отказ (остановка по массовому сдвигу — только цены из данных конкурентов, 0042)
CREATE FUNCTION channel_data.price_decision_basis_halt_guard() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  halt_id uuid;
BEGIN
  IF NEW.outcome = 'APPROVED' THEN
    halt_id := channel_data.price_basis_halt_for(NEW.tenant_id, NEW.write_scope_id);
    IF halt_id IS NOT NULL THEN
      RAISE EXCEPTION 'pricing is halted for a wrong price basis by pricing_halt % for write_scope % (Р-116)', halt_id, NEW.write_scope_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER ac_price_decision_basis_halt_guard BEFORE INSERT ON channel_data.price_decision
  FOR EACH ROW EXECUTE FUNCTION channel_data.price_decision_basis_halt_guard();

-- Создание и отправка записи цены при остановке по базе цены — отказ, как остановка человеком (0042)
CREATE FUNCTION tenant_data.channel_write_basis_halt_guard() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  halt_id uuid;
BEGIN
  IF NEW.field <> 'PRICE' OR (TG_OP = 'UPDATE' AND NOT (NEW.status = 'DISPATCHED' AND OLD.status IS DISTINCT FROM 'DISPATCHED')) THEN
    RETURN NEW;
  END IF;
  halt_id := channel_data.price_basis_halt_for(NEW.tenant_id, NEW.write_scope_id);
  IF halt_id IS NOT NULL THEN
    RAISE EXCEPTION 'pricing is halted for a wrong price basis by pricing_halt % for write_scope % (Р-116)', halt_id, NEW.write_scope_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER bc_channel_write_basis_halt_guard BEFORE INSERT OR UPDATE OF status ON tenant_data.channel_write
  FOR EACH ROW EXECUTE FUNCTION tenant_data.channel_write_basis_halt_guard();

