CREATE OR REPLACE FUNCTION security.explanation_field_kinds() RETURNS jsonb
  LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
  SELECT '{"$.format":{"k":"enum","v":["r80.1"]},"$.snapshot.source":{"k":"code"},"$.sanity.checks[].rule":{"k":"enum","v":["CHANNEL_HALTED","STRUCTURE","FRESHNESS","CHANNEL_MASS_SHIFT","UNIT_SCALE","COST_ANCHOR","INTERNAL_ANCHOR","CROSS_CHANNEL_ANCHOR","HISTORY_ANCHOR"]},"$.sanity.checks[].outcome":{"k":"enum","v":["PASS","FAIL","SKIPPED"]},"$.sanity.anchorsUsed":{"k":"codeList"},"$.strategy.intentClass":{"k":"enum","v":["NO_OP"]},"$.strategy.currentMinor":{"k":"money","n":true},"$.strategy.currency":{"k":"currency"},"$.strategy.boundsAtStrategy.minMinor":{"k":"money"},"$.strategy.boundsAtStrategy.maxMinor":{"k":"money"},"$.strategy.boundsAtStrategy.currency":{"k":"currency"},"$.gate.failed.check":{"k":"code"},"$.gate.minMarginBp":{"k":"bp"},"$.gate.fx.source":{"k":"enum","v":["ECB"]},"$.gate.fx.rateDate":{"k":"date"},"$.gate.fx.base":{"k":"enum","v":["EUR"]},"$.gate.fx.quote":{"k":"currency"},"$.gate.fx.rateMicros":{"k":"rateMicros"},"$.gate.fx.from":{"k":"currency"},"$.gate.fx.to":{"k":"currency"},"$.gate.fx.sourceAmountMinor":{"k":"money"},"$.gate.fx.convertedAmountMinor":{"k":"money"},"$.gate.fx.rounding":{"k":"enum","v":["UP","NEAREST"]},"$.context.channelHalt.haltId":{"k":"uuid"},"$.context.channelHalt.reasonCode":{"k":"enum","v":["CHANNEL_MASS_SHIFT","CHANNEL_PRICE_BASIS_MISMATCH"]},"$.context.channelHalt.marketplace":{"k":"id","n":true},"$.context.channelHalt.haltedAt":{"k":"instant"},"$.context.priceStop.stopId":{"k":"uuid"},"$.context.priceStop.scope":{"k":"enum","v":["TENANT","CHANNEL_ACCOUNT","STOREFRONT"]},"$.context.priceStop.channelAccountId":{"k":"uuid","n":true},"$.context.priceStop.marketplace":{"k":"id","n":true},"$.context.priceStop.stoppedAt":{"k":"instant"},"$.context.priceStop.stoppedByMembershipId":{"k":"uuid"}}'::jsonb
$$;

-- ---------------------------------------------------------------------------
-- 3. Находка 7 ревью шага 21
-- ---------------------------------------------------------------------------
ALTER FUNCTION tenant_data.row_in_current_transaction(xid) VOLATILE PARALLEL RESTRICTED;
COMMENT ON FUNCTION tenant_data.row_in_current_transaction(xid) IS
  'Р-88 (0078): видимая строка создана текущей транзакцией или её подтранзакцией. Читает состояние транзакции — VOLATILE PARALLEL RESTRICTED (находка 7 ревью шага 21). Эпоха xmin берётся у верхней транзакции: подтранзакция, получившая идентификатор после перехода эпохи (раз в 2^32 транзакций), не распознаётся — принятое ограничение, принятый риск 17';

-- ---------------------------------------------------------------------------
-- 4. Р-114
-- ---------------------------------------------------------------------------
COMMENT ON CONSTRAINT channel_capability_channel_min_price_only_kaufland ON platform.channel_capability IS
  'Р-12, Р-111, Р-114: поле порога цены площадки описывается только для Kaufland (minimum_price включает Smart Pricing). Amazon minimum_seller_allowed_price не пишется никогда: по Р-114 он создаёт второй набор границ на стороне канала (базовая цена обязана лежать между ними), а не включает репрайсер Amazon';
COMMENT ON CONSTRAINT write_scope_smart_pricing_only_kaufland ON tenant_data.write_scope IS
  'Р-12, Р-111, Р-114: режим, в котором пишется поле-порог площадки, существует только у Kaufland';

COMMIT;
